import test from 'node:test';
import assert from 'node:assert/strict';
import { invoiceTotal } from '../src/invoice.js';
import { percentOf } from '../src/money.js';

test('a round order totals exactly', () => {
  assert.equal(invoiceTotal({ items: [{ priceCents: 1000, quantity: 2 }], discountPercent: 10, taxPercent: 10 }), 1980);
});

test('discounted taxed order rounds each percentage amount half up', () => {
  // Discount 1999 * 15% = 299.85 -> 300; net 1699.
  // Tax 1699 * 8% = 135.92 -> 136; total 1835.
  assert.equal(invoiceTotal({ items: [{ priceCents: 1999, quantity: 1 }], discountPercent: 15, taxPercent: 8 }), 1835);
});

test('percentage amounts round to the nearest cent, halves up', () => {
  assert.equal(percentOf(1999, 15), 300); // 299.85 rounds up
  assert.equal(percentOf(1699, 8), 136); // 135.92 rounds up
  assert.equal(percentOf(1000, 5), 50); // exact
  assert.equal(percentOf(1010, 5), 51); // 50.5 rounds up
  assert.equal(percentOf(1, 50), 1); // 0.5 rounds up
  assert.equal(percentOf(1, 49), 0); // 0.49 rounds down
  assert.equal(percentOf(1998, 15), 300); // 299.7 rounds up
});

